entries[33869] = { ["name"] = "Rezept: Gebratene Blutflosse", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (300)\nBenutzen: Lehrt Euch, wie man gebratene Blutflossen zubereitet.\nVerkaufspreis:\nGebratene Blutflosse\nBenötigt Stufe 55\nBenutzen: Stellt im Verlauf von 30 Sek. 4320 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 30 Min. lang einen um 8 erhöhten Widerstand gegen alle Arten von Magie.\nVerkaufspreis:\nBenötigt Blutflossenwels" }
entries[33870] = { ["name"] = "Rezept: Schädelfischsuppe", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (325)\nBenutzen: Lehrt Euch, wie man Schädelfischsuppe zubereitet.\nVerkaufspreis:\nSchädelfischsuppe\nBenötigt Stufe 65\nBenutzen: Stellt im Verlauf von 30 Sek. insgesamt 7200 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Trinken verbringt, werdet Ihr erleuchtet und erhaltet 30 Min. lang 20 kritische Zaubertrefferwertung und Willenskraft.\nVerkaufspreis:\nBenötigt Mondschädelfisch" }
